CYAN = "\033[96m"
GREEN = "\033[92m"
RED = "\033[91m"
BOLD = "\033[1m"
DIM = "\033[2m"
RESET = "\033[0m"
CLR = "\033[2K"

_CODEX_START = "<!-- paperclip-skill-start -->"
_CODEX_END = "<!-- paperclip-skill-end -->"

# The installed agent skill is a lightweight pointer (placeholder.md) that
# tells the agent to run `paperclip skill` for the full documentation. Older
# servers only publish the full skill at /skills/skill.md, so that stays as
# a fallback.
_PLACEHOLDER_ENDPOINT = "/skills/placeholder.md"
_LEGACY_SKILL_ENDPOINT = "/skills/skill.md"
# Full documentation printed by the singular `paperclip skill` command.
_FULL_SKILL_ENDPOINT = "/skills/full_skill.md"

_MAX_PACKAGE_FILES = 200
_MAX_PACKAGE_FILE_BYTES = 5 * 1024 * 1024
_MAX_PACKAGE_BYTES = 20 * 1024 * 1024
_MAX_MANIFEST_BYTES = 256 * 1024

# Marks skill content that has already had the repos sections removed, so the
# strip is idempotent (refresh runs on every login / every few hours).
_REPOS_DISABLED_MARKER = "<!-- paperclip-repos-disabled -->"


def skill_request_headers() -> dict[str, str]:
    """Return available auth headers without forcing an interactive login."""
    bearer = os.getenv("PAPERCLIP_BEARER_TOKEN", "").strip()
    if bearer:
        return {"Authorization": f"Bearer {bearer}"}
    api_key = os.getenv("PAPERCLIP_API_KEY", "").strip()
    if api_key:
        return {"X-API-Key": api_key}
    credentials = Credentials.load()
    if credentials is None:
        return {}
    try:
        return {"Authorization": f"Bearer {credentials.get_id_token()}"}
    except RuntimeError:
        return {}

AGENTS = [
    {
        "key": "claude-code",
        "label": "Claude Code",
        "desc": ".claude/skills/paperclip/SKILL.md",
    },
    {
        "key": "cursor",
        "label": "Cursor",
        "desc": ".cursor/skills/paperclip/SKILL.md",
    },
    {
        "key": "codex",
        "label": "Codex",
        "desc": ".agents/skills/paperclip/SKILL.md",
    },
]


def fetch_full_skill(base_url: str, timeout: int = 10) -> str | None:
    """Fetch the full skill documentation (for `paperclip skill`).

    Prefers full_skill.md; falls back to the legacy skill.md name. The
    repos-disabled preference is applied so agents never see instructions
    for a feature that is turned off locally.

    Uses an ETag-validated local cache: the previous body and its ETag are
    kept in ~/.paperclip/cache, and each call revalidates with
    ``If-None-Match``. Unchanged content costs a single 304 round-trip
    instead of a full transfer, while changed content is picked up live.
    If the server is unreachable, the cached copy is served as a fallback.
    """
    cached_body, cached_etag = _read_skill_cache(base_url)
    headers = skill_request_headers()
    if cached_etag:
        headers["If-None-Match"] = cached_etag

    content: str | None = None
    for endpoint in (_FULL_SKILL_ENDPOINT, _LEGACY_SKILL_ENDPOINT):
        try:
            resp = requests.get(f"{base_url}{endpoint}", timeout=timeout, headers=headers)
            if resp.status_code == 304 and cached_body:
                content = cached_body
                break
            resp.raise_for_status()
        except Exception:
            continue
        if resp.text.strip():
            content = resp.text
            _write_skill_cache(base_url, content, resp.headers.get("ETag"))
            break

    if content is None:
        content = cached_body  # offline fallback

    if content is None:
        return None
    if not config.repos_enabled():
        content = strip_repos_sections(content)
    return content


def fetch_skill_content(
    base_url: str,
    name: str,
    *,
    timeout: int = 10,
) -> str | None:
    """Fetch a domain skill or nested routine phase with authenticated caching."""
    endpoints = [f"/skills/skills/{name}.md"]
    if "/" not in name:
        endpoints.append(f"/skills/skills/{name}/SKILL.md")

    request_headers = skill_request_headers()
    auth_marker = "|".join(
        f"{key.lower()}:{value}" for key, value in sorted(request_headers.items())
    )
    cache_key = hashlib.sha256(
        f"{base_url}|{name}|{auth_marker}".encode()
    ).hexdigest()[:24]
    cache_file = config.PAPERCLIP_DIR / "cache" / "skills" / f"{cache_key}.json"
    cached_body: str | None = None
    cached_etag: str | None = None
    cached_endpoint: str | None = None
    try:
        cached = json.loads(cache_file.read_text())
        if isinstance(cached.get("body"), str) and cached["body"].strip():
            cached_body = cached["body"]
        if isinstance(cached.get("etag"), str) and cached["etag"]:
            cached_etag = cached["etag"]
        if isinstance(cached.get("endpoint"), str):
            cached_endpoint = cached["endpoint"]
    except Exception:
        pass

    for endpoint in endpoints:
        headers = dict(request_headers)
        if cached_etag and cached_endpoint == endpoint:
            headers["If-None-Match"] = cached_etag
        try:
            resp = requests.get(
                f"{base_url}{endpoint}",
                timeout=timeout,
                headers=headers,
            )
            if resp.status_code == 304 and cached_body:
                return cached_body
            if resp.status_code == 404:
                continue
            resp.raise_for_status()
        except Exception:
            continue
        if not resp.text.strip():
            continue
        try:
            cache_file.parent.mkdir(parents=True, exist_ok=True)
            payload = {
                "endpoint": endpoint,
                "etag": resp.headers.get("ETag"),
                "body": resp.text,
            }
            tmp = cache_file.with_name(f"{cache_file.name}.{os.getpid()}.tmp")
            tmp.write_text(json.dumps(payload))
            os.replace(tmp, cache_file)
        except Exception:
            pass
        return resp.text
    return cached_body


def _skill_cache_file(base_url: str) -> Path:
    """Cache location for the full skill, keyed by server (dev/staging/prod)."""
    key = hashlib.sha256(base_url.encode("utf-8")).hexdigest()[:12]
    return config.PAPERCLIP_DIR / "cache" / f"full_skill-{key}.json"


def _read_skill_cache(base_url: str) -> tuple[str | None, str | None]:
    """Return (body, etag) from the cache, or (None, None) if unusable."""
    try:
        data = json.loads(_skill_cache_file(base_url).read_text())
        body = data.get("body")
        etag = data.get("etag")
        if isinstance(body, str) and body.strip():
            return body, etag if isinstance(etag, str) and etag else None
    except Exception:
        pass
    return None, None


def _write_skill_cache(base_url: str, body: str, etag: str | None) -> None:
    """Atomically persist the fetched skill body and its ETag (if any).

    The body is cached even without an ETag so the offline fallback works;
    revalidation then just degrades to a full fetch.
    """
    try:
        f = _skill_cache_file(base_url)
        f.parent.mkdir(parents=True, exist_ok=True)
        payload = json.dumps({"etag": etag, "body": body})
        tmp = f.with_name(f"{f.name}.{os.getpid()}.tmp")
        tmp.write_text(payload)
        os.replace(tmp, f)
    except Exception:
        pass


def fetch_agent_skill(base_url: str, timeout: int = 15) -> str | None:
    """Fetch the content to install as the agent SKILL.md.

    Prefers the lightweight placeholder; falls back to the legacy full
    skill.md for servers that don't publish placeholder.md yet. Returns
    None if neither yields valid skill content.
    """
    for endpoint in (_PLACEHOLDER_ENDPOINT, _LEGACY_SKILL_ENDPOINT):
        try:
            resp = requests.get(
                f"{base_url}{endpoint}",
                timeout=timeout,
                headers=skill_request_headers(),
            )
            resp.raise_for_status()
        except Exception:
            continue
        if resp.text.startswith("---\nname:"):
            return resp.text
    return None


# ── Install registry ──────────────────────────────────────────────
#
# Skill files installed before the registry existed can only be found by
# scanning, so refresh also discovers files in the cwd, its ancestors, and
# the home directory, and backfills them into the registry.

_SKILL_RELATIVE_PATHS = (
    Path(".claude") / "skills" / "paperclip" / "SKILL.md",
    Path(".cursor") / "skills" / "paperclip" / "SKILL.md",
    Path(".agents") / "skills" / "paperclip" / "SKILL.md",
)


def _safe_home() -> Path | None:
    """Path.home() that tolerates environments without a home directory."""
    try:
        return Path.home()
    except (RuntimeError, OSError):
        return None


def _registry_file() -> Path:
    return config.PAPERCLIP_DIR / "installed_skills.json"


def _agent_for_path(path: Path) -> str:
    parts = path.parts
    for marker, agent in (
        (".claude", "claude-code"),
        (".cursor", "cursor"),
        (".agents", "codex"),
    ):
        if marker in parts:
            return agent
    return "legacy"


def _record_for_path(path: Path) -> dict:
    """Convert a legacy registry path to a structured core-skill record."""
    kind = "legacy_codex" if path.name == "AGENTS.md" else "system"
    return {
        "skill": "paperclip",
        "kind": kind,
        "agent": _agent_for_path(path),
        "root": str(path.parent),
        "entry": str(path),
    }


def _valid_registry_record(raw: object) -> dict | None:
    if not isinstance(raw, dict):
        return None
    skill = raw.get("skill")
    kind = raw.get("kind")
    agent = raw.get("agent")
    root = raw.get("root")
    entry = raw.get("entry")
    if (
        not isinstance(skill, str)
        or not skill
        or kind not in {"system", "legacy_codex", "single", "package"}
        or not isinstance(agent, str)
        or not isinstance(root, str)
        or not os.path.isabs(root)
        or not isinstance(entry, str)
        or not os.path.isabs(entry)
    ):
        return None
    if kind in {"single", "package"}:
        marker = {
            "claude-code": ".claude",
            "cursor": ".cursor",
            "codex": ".agents",
        }.get(agent)
        root_path = Path(root)
        entry_path = Path(entry)
        if (
            marker is None
            or any(part == ".." for part in root_path.parts)
            or not skill[0].isalnum()
            or any(
                ch not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
                for ch in skill
            )
            or root_path.name != skill
            or root_path.parent.name != "skills"
            or root_path.parent.parent.name != marker
            or entry_path != root_path / "SKILL.md"
        ):
            return None
    record = {
        "skill": skill,
        "kind": kind,
        "agent": agent,
        "root": root,
        "entry": entry,
    }
    if isinstance(raw.get("manifest"), str):
        record["manifest"] = raw["manifest"]
    if isinstance(raw.get("description"), str):
        record["description"] = raw["description"]
    return record


def _read_install_registry() -> list[dict]:
    """Read v2 installs and migrate valid legacy ``paths`` entries in memory."""
    try:
        data = json.loads(_registry_file().read_text())
    except Exception:
        return []
    if not isinstance(data, dict):
        return []

    records: list[dict] = []
    raw_installs = data.get("installs", [])
    if isinstance(raw_installs, list):
        for raw in raw_installs:
            record = _valid_registry_record(raw)
            if record is not None:
                records.append(record)

    known_entries = {record["entry"] for record in records}
    raw_paths = data.get("paths", [])
    if isinstance(raw_paths, list):
        for raw_path in raw_paths:
            if (
                isinstance(raw_path, str)
                and os.path.isabs(raw_path)
                and raw_path not in known_entries
            ):
                records.append(_record_for_path(Path(raw_path)))
                known_entries.add(raw_path)
    return records


def _read_registry() -> set[Path]:
    """Backward-compatible path view of the structured install registry."""
    return {Path(record["entry"]) for record in _read_install_registry()}


def _write_install_registry(installs: Iterable[dict]) -> None:
    """Atomically persist the registry (temp file + rename).

    A concurrent `paperclip` process reading mid-write must never see a
    truncated file, which `_read_registry` would treat as corrupt and drop.
    """
    try:
        unique: dict[tuple[str, str, str], dict] = {}
        for raw in installs:
            record = _valid_registry_record(raw)
            if record is not None:
                key = (record["skill"], record["agent"], record["entry"])
                unique[key] = record
        records = sorted(
            unique.values(),
            key=lambda item: (item["skill"], item["agent"], item["entry"]),
        )
        f = _registry_file()
        f.parent.mkdir(parents=True, exist_ok=True)
        payload = (
            json.dumps(
                {
                    "version": 2,
                    # Keep paths so older Paperclip versions can still refresh core
                    # installs. Domain skills must not appear here: older clients
                    # treat every legacy path as the core Paperclip pointer.
                    "paths": sorted(
                        record["entry"]
                        for record in records
                        if record["kind"] in {"system", "legacy_codex"}
                    ),
                    "installs": records,
                },
                indent=2,
            )
            + "\n"
        )
        tmp = f.with_name(f"{f.name}.{os.getpid()}.tmp")
        tmp.write_text(payload)
        os.replace(tmp, f)
    except Exception:
        pass


def _write_registry(paths: Iterable[Path]) -> None:
    """Compatibility wrapper used by older tests and core discovery."""
    _write_install_registry(_record_for_path(Path(path)) for path in set(paths))


def _register_install_records(installs: Iterable[dict]) -> None:
    existing = _read_install_registry()
    merged = existing + list(installs)
    before = {(record["skill"], record["agent"], record["entry"]): record for record in existing}
    after = {
        (record["skill"], record["agent"], record["entry"]): record
        for record in merged
        if _valid_registry_record(record) is not None
    }
    if after != before:
        _write_install_registry(merged)


def _register_skill_paths(paths: Iterable[Path]) -> None:
    """Add legacy/core *paths* to the registry, keeping domain installs."""
    _register_install_records(_record_for_path(Path(path)) for path in paths)


def _candidate_dirs() -> list[Path]:
    """Directories scanned for existing installs: cwd, its ancestors, home."""
    dirs: list[Path] = []
    try:
        cwd = Path.cwd()
        dirs = [cwd, *cwd.parents]
    except OSError:
        pass  # cwd was deleted from under us
    home = _safe_home()
    if home is not None and home not in dirs:
        dirs.append(home)
    return dirs


# Bounded scan of the home directory (used by interactive `paperclip update`
# only — too slow for the background refresh). Depth-limited and skips
# directories that are large and can't contain a skill install.
_HOME_SCAN_MAX_DEPTH = 4
_HOME_SCAN_SKIP_DIRS = {
    "node_modules",
    "Library",
    "Applications",
    ".Trash",
    ".git",
    ".cache",
    ".npm",
    ".nvm",
    ".cargo",
    ".rustup",
    ".venv",
    "venv",
    "site-packages",
    "__pycache__",
    # Skill parents themselves — checked via _SKILL_RELATIVE_PATHS, no need
    # to descend into them.
    ".claude",
    ".cursor",
    ".agents",
}


def _scan_home_for_skills() -> set[Path]:
    """Find all installed SKILL.md files under the home directory.

    Bounded by depth and a directory denylist; never follows symlinks
    (`os.walk` default), so symlink loops can't hang the scan. Unreadable
    directories are silently skipped.
    """
    found: set[Path] = set()
    home = _safe_home()
    if home is None or not home.is_dir():
        return found
    base_depth = len(home.parts)
    for root, dirs, _files in os.walk(home):
        root_path = Path(root)
        depth = len(root_path.parts) - base_depth
        if depth >= _HOME_SCAN_MAX_DEPTH:
            dirs[:] = []
        else:
            dirs[:] = [d for d in dirs if d not in _HOME_SCAN_SKIP_DIRS]
        for rel in _SKILL_RELATIVE_PATHS:
            p = root_path / rel
            try:
                if p.is_file():
                    found.add(p)
            except OSError:
                continue
    return found


# Legacy AGENTS.md files are read in full to look for the sentinel; cap the
# size so a pathological multi-GB file can't stall a background refresh.
_LEGACY_FILE_MAX_BYTES = 10 * 1024 * 1024


def _is_legacy_codex_file(path: Path) -> bool:
    """True if *path* is an AGENTS.md containing the paperclip sentinel."""
    try:
        if not path.is_file() or path.stat().st_size > _LEGACY_FILE_MAX_BYTES:
            return False
        return _CODEX_START in path.read_text(errors="replace")
    except OSError:
        return False


def _display_path(path: Path) -> str:
    """Path relative to cwd or home when possible, for friendly output."""
    try:
        return str(path.relative_to(Path.cwd()))
    except (ValueError, OSError):
        pass
    home = _safe_home()
    if home is not None:
        try:
            return "~/" + str(path.relative_to(home))
        except ValueError:
            pass
    return str(path)


# ── Repos feature: strip skill content when disabled ─────────────

# Top-level (## ) sections removed wholesale when repos are disabled.
_REPOS_SECTION_PREFIXES = ("Paper Repositories",)
# Sub-level (### ) sections removed within otherwise-kept sections.
_REPOS_SUBSECTION_PREFIXES = ("Paper Repositories",)
# Stray lines (tips / workflow steps) that only make sense with repos.
_REPOS_LINE_SUBSTRINGS = (
    "**Cite**:",
    "check `status`",
    "papers marked",
)

_REPOS_DISABLED_NOTE = (
    f"{_REPOS_DISABLED_MARKER}\n"
    "## Paper repositories (disabled)\n\n"
    "The paper-repository feature (`init`, `add`, `commit`, `status`, "
    "`branch`, `merge`, and verified citations) is turned off in this "
    "environment. Do not use those commands. Cite sources directly, "
    "checking each claim against the document's full text first.\n"
)


def _heading_level(line: str) -> int:
    """Return the markdown heading level (1=#, 2=##, ...) or 0 if not a heading."""
    stripped = line.lstrip()
    n = 0
    for ch in stripped:
        if ch == "#":
            n += 1
        else:
            break
    if n and stripped[n : n + 1] == " ":
        return n
    return 0


def strip_repos_sections(content: str) -> str:
    """Remove paper-repository instructions from skill.md content.

    Used when the user has disabled the repos feature (``paperclip
    repos-feature disable``) so the coding agent is never told to use
    ``init``/``add``/``commit``/etc. Works on Markdown headings, so it
    tolerates edits to the
    surrounding prose, and is idempotent via ``_REPOS_DISABLED_MARKER``.
    """
    if _REPOS_DISABLED_MARKER in content:
        return content

    lines = content.splitlines()
    out: list[str] = []
    i, n = 0, len(lines)
    while i < n:
        line = lines[i]
        level = _heading_level(line)

        if level == 2:
            title = line.lstrip()[2:].strip()
            if title.startswith(_REPOS_SECTION_PREFIXES):
                # Drop the whole section until the next ## (or EOF).
                i += 1
                while i < n and _heading_level(lines[i]) != 2:
                    i += 1
                continue
            if title.startswith("Citations"):
                # Keep the section + citation format, drop the repo workflow.
                out.append(line)
                out.append("")
                out.append(
                    "**Verify before citing.** Confirm each claim against the "
                    "source's full text before citing it."
                )
                out.append("")
                i += 1
                while i < n and _heading_level(lines[i]) not in (2, 3):
                    i += 1
                continue

        if level == 3 and line.lstrip()[3:].strip().startswith(_REPOS_SUBSECTION_PREFIXES):
            # Drop the subsection until the next ### or ## (or EOF).
            i += 1
            while i < n and _heading_level(lines[i]) not in (2, 3):
                i += 1
            continue

        if level == 0 and any(s in line for s in _REPOS_LINE_SUBSTRINGS):
            i += 1
            continue

        out.append(line)
        i += 1

    result = "\n".join(out).rstrip() + "\n\n" + _REPOS_DISABLED_NOTE
    return result


# ── File writers ─────────────────────────────────────────────────


def _write_claude_code(content: str, target: Path) -> Path:
    skill_dir = target / ".claude" / "skills" / "paperclip"
    skill_dir.mkdir(parents=True, exist_ok=True)
    path = skill_dir / "SKILL.md"
    path.write_text(content)
    return path


def _write_cursor(content: str, target: Path) -> Path:
    skill_dir = target / ".cursor" / "skills" / "paperclip"
    skill_dir.mkdir(parents=True, exist_ok=True)
    path = skill_dir / "SKILL.md"
    path.write_text(content)
    return path


def _write_codex(content: str, target: Path) -> Path:
    skill_dir = target / ".agents" / "skills" / "paperclip"
    skill_dir.mkdir(parents=True, exist_ok=True)
    path = skill_dir / "SKILL.md"
    path.write_text(content)
    return path


def _write_codex_legacy(content: str, target: Path) -> Path:
    """Write to AGENTS.md with sentinel comments (legacy Codex format)."""
    path = target / "AGENTS.md"
    wrapped = f"{_CODEX_START}\n{content}\n{_CODEX_END}\n"

    if path.exists():
        existing = path.read_text()
        if _CODEX_START in existing:
            i = existing.index(_CODEX_START)
            j = existing.index(_CODEX_END) + len(_CODEX_END)
            nl = existing.find("\n", j)
            j = nl + 1 if nl != -1 else j
            path.write_text(existing[:i] + wrapped + existing[j:])
        else:
            with open(path, "a") as f:
                f.write("\n" + wrapped)
    else:
        path.write_text(wrapped)

    return path


# ── Multi-select checkbox ─────────────────────────────────────────


def _checkbox(options: list, title: str, defaults: list[int] | None = None) -> list[int]:
    """Multi-select checkbox — arrows + space on TTY, comma-list fallback."""
    if not sys.stdin.isatty():
        return _checkbox_numbered(options, title, defaults)
    try:
        import termios  # noqa: F811
        import tty  # noqa: F811

        return _checkbox_arrows(options, title, termios, tty, defaults)
    except (ImportError, AttributeError):
        return _checkbox_numbered(options, title, defaults)


def _checkbox_numbered(options: list, title: str, defaults: list[int] | None = None) -> list[int]:
    click.echo(f"\n  {BOLD}{title}{RESET}\n")
    for i, opt in enumerate(options):
        click.echo(f"    {i + 1}) {opt['label']}  {DIM}{opt['desc']}{RESET}")
    click.echo()
    while True:
        raw = click.prompt("  Select (e.g. 1,2 or all)", default="1")
        if raw.strip().lower() == "all":
            return list(range(len(options)))
        try:
            chosen = [int(x.strip()) - 1 for x in raw.split(",") if x.strip()]
            if chosen and all(0 <= v < len(options) for v in chosen):
                return list(dict.fromkeys(chosen))
        except ValueError:
            pass
        click.echo(f"  Enter numbers 1\u2013{len(options)} separated by commas, or 'all'")


def _checkbox_arrows(  # type: ignore[no-untyped-def]
    options: list,
    title: str,
    termios,
    tty,
    defaults: list[int] | None = None,
) -> list[int]:
    idx = 0
    n = len(options)
    selected: set[int] = set(defaults) if defaults else set()
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    cols = shutil.get_terminal_size((80, 24)).columns
    # n option lines; hint has no trailing \n so cursor stays on it
    render_lines = n

    def _trunc(text: str, width: int) -> str:
        """Truncate visible text (ignoring ANSI escapes) to *width* columns."""
        import re

        visible = re.sub(r"\x1b\[[0-9;]*m", "", text)
        if len(visible) <= width:
            return text
        # Walk the original string keeping track of visible length
        out: list[str] = []
        vlen = 0
        i = 0
        while i < len(text) and vlen < width - 1:
            if text[i] == "\x1b":
                j = text.index("m", i) + 1
                out.append(text[i:j])
                i = j
            else:
                out.append(text[i])
                vlen += 1
                i += 1
        out.append(RESET + "\u2026")
        return "".join(out)

    def render(first: bool = False) -> None:
        if not first:
            sys.stdout.write(f"\033[{render_lines}A\r")
        for i, opt in enumerate(options):
            check = f"{GREEN}\u2713{RESET}" if i in selected else " "
            cursor = f"{CYAN}\u203a{RESET}" if i == idx else " "
            line = f"   {cursor} [{check}] {opt['label']}  {DIM}{opt['desc']}{RESET}"
            sys.stdout.write(f"{CLR}{_trunc(line, cols)}\n")
        sys.stdout.write(
            f"{CLR}  {DIM}\u2191/\u2193 navigate \u00b7 space select \u00b7 enter confirm \u00b7 q quit{RESET}"  # noqa: E501
        )
        sys.stdout.flush()

    click.echo(f"\n  {BOLD}{title}{RESET}\n")
    render(first=True)

    try:
        tty.setcbreak(fd)
        while True:
            ch = sys.stdin.read(1)
            if ch == "\x1b":
                b = sys.stdin.read(1)
                if b == "[":
                    arrow = sys.stdin.read(1)
                    if arrow == "A":
                        idx = (idx - 1) % n
                    elif arrow == "B":
                        idx = (idx + 1) % n
                render()
            elif ch == " ":
                if idx in selected:
                    selected.discard(idx)
                else:
                    selected.add(idx)
                render()
            elif ch in ("\r", "\n"):
                sys.stdout.write("\n\n")
                sys.stdout.flush()
                if not selected:
                    return [idx]
                return sorted(selected)
            elif ch in ("q", "\x03"):
                sys.stdout.write("\n")
                raise SystemExit(0)
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)


# ── Domain skill packages ────────────────────────────────────────


def validate_installable_skill_name(name: str) -> str:
    """Return a safe skill directory name or raise a Click usage error."""
    normalized = name.removesuffix(".md")
    if normalized == "paperclip":
        raise click.UsageError("the core Paperclip skill is installed with `paperclip install`")
    if (
        not normalized
        or len(normalized) > 128
        or not normalized[0].isalnum()
        or any(
            ch not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
            for ch in normalized
        )
    ):
        raise click.UsageError("invalid skill name")
    return normalized


def _safe_package_path(raw: object) -> Path:
    if not isinstance(raw, str) or not raw or len(raw) > 512 or "\\" in raw:
        raise ValueError("invalid package path")
    path = Path(raw)
    if path.is_absolute() or any(part in {"", ".", ".."} for part in path.parts):
        raise ValueError(f"unsafe package path: {raw}")
    if any(ord(ch) < 32 for ch in raw):
        raise ValueError("invalid package path")
    return path


def _package_source_endpoint(name: str, raw: object) -> str:
    """Resolve a manifest source below ``/skills/skills``.

    A package may source its entry from the adjacent legacy ``<name>.md``
    endpoint using ``../<name>.md``. Normalization may leave the package
    directory, but never the served skills root.
    """
    if (
        not isinstance(raw, str)
        or not raw
        or len(raw) > 512
        or raw.startswith("/")
        or "\\" in raw
        or any(ord(ch) < 32 for ch in raw)
        or any(
            ch not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_./-"
            for ch in raw
        )
    ):
        raise ValueError("invalid package source")
    if raw.startswith("../") and raw != f"../{name}.md":
        raise ValueError("package source may only use its legacy adjacent entry")
    normalized = posixpath.normpath(f"{name}/{raw}")
    if normalized == ".." or normalized.startswith("../"):
        raise ValueError("unsafe package source")
    return f"/skills/skills/{normalized}"


def _response_bytes(resp, limit: int) -> bytes:  # type: ignore[no-untyped-def]
    length = resp.headers.get("Content-Length") if hasattr(resp, "headers") else None
    if length:
        try:
            if int(length) > limit:
                raise ValueError("download exceeds size limit")
        except ValueError as exc:
            if str(exc) == "download exceeds size limit":
                raise
    if hasattr(resp, "iter_content"):
        chunks: list[bytes] = []
        total = 0
        for chunk in resp.iter_content(chunk_size=64 * 1024):
            if not chunk:
                continue
            total += len(chunk)
            if total > limit:
                raise ValueError("download exceeds size limit")
            chunks.append(chunk)
        return b"".join(chunks)
    body = getattr(resp, "content", None)
    if not isinstance(body, bytes):
        body = str(getattr(resp, "text", "")).encode("utf-8")
    if len(body) > limit:
        raise ValueError("download exceeds size limit")
    return body


def _download(base_url: str, endpoint: str, limit: int) -> bytes:
    resp = requests.get(
        f"{base_url}{endpoint}",
        timeout=15,
        stream=True,
        headers=skill_request_headers(),
    )
    resp.raise_for_status()
    return _response_bytes(resp, limit)


def fetch_skill_manifest(base_url: str, name: str) -> dict | None:
    """Fetch and minimally validate a package manifest; return None on 404."""
    endpoint = f"/skills/skills/{name}/manifest.json"
    try:
        resp = requests.get(
            f"{base_url}{endpoint}",
            timeout=10,
            stream=True,
            headers=skill_request_headers(),
        )
        if getattr(resp, "status_code", None) == 404:
            return None
        resp.raise_for_status()
        raw = _response_bytes(resp, _MAX_MANIFEST_BYTES)
        manifest = json.loads(raw.decode("utf-8"))
    except requests.exceptions.HTTPError:
        raise
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
        raise ValueError(f"invalid package manifest: {exc}") from exc
    if not isinstance(manifest, dict):
        raise ValueError("invalid package manifest")
    if manifest.get("schema_version") != "paperclip.skill-package.v1":
        raise ValueError("unsupported package manifest schema")
    if manifest.get("name") not in (None, name):
        raise ValueError("package manifest name does not match requested skill")
    if manifest.get("entry") != "SKILL.md":
        raise ValueError("package manifest entry must be SKILL.md")
    files = manifest.get("files")
    if not isinstance(files, list) or not files:
        raise ValueError("package manifest has no files")
    if len(files) > _MAX_PACKAGE_FILES:
        raise ValueError("package contains too many files")
    return manifest


def _package_files(base_url: str, name: str, manifest: dict) -> dict[Path, bytes]:
    descriptors: list[tuple[Path, str, str, int]] = []
    destinations: set[Path] = set()
    for item in manifest["files"]:
        if isinstance(item, dict):
            destination = _safe_package_path(item.get("path"))
            source = _package_source_endpoint(name, item.get("source", item.get("path")))
            checksum = item.get("sha256", item.get("checksum"))
            if isinstance(checksum, str) and checksum.startswith("sha256:"):
                checksum = checksum.removeprefix("sha256:")
            if (
                not isinstance(checksum, str)
                or len(checksum) != 64
                or any(ch not in "0123456789abcdefABCDEF" for ch in checksum)
            ):
                raise ValueError(f"missing or invalid checksum for {destination}")
            size = item.get("size")
            if not isinstance(size, int) or isinstance(size, bool) or size < 0:
                raise ValueError(f"missing or invalid size for {destination}")
        else:
            raise ValueError("canonical package manifests require file descriptors")
        if destination in destinations:
            raise ValueError(f"duplicate package path: {destination}")
        destinations.add(destination)
        descriptors.append((destination, source, checksum, size))

    entry = _safe_package_path(manifest.get("entry", "SKILL.md"))
    if entry not in destinations:
        raise ValueError("package entry is not listed in manifest")

    files: dict[Path, bytes] = {}
    total = 0
    for destination, source, checksum, expected_size in descriptors:
        body = _download(
            base_url,
            source,
            _MAX_PACKAGE_FILE_BYTES,
        )
        total += len(body)
        if total > _MAX_PACKAGE_BYTES:
            raise ValueError("package exceeds total size limit")
        if len(body) != expected_size:
            raise ValueError(f"size mismatch for {destination}")
        if checksum and hashlib.sha256(body).hexdigest().lower() != checksum.lower():
            raise ValueError(f"checksum mismatch for {destination}")
        files[destination] = body
    return files


def _single_skill_file(base_url: str, name: str, catalog_entry: dict | None) -> dict[Path, bytes]:
    body = _download(base_url, f"/skills/skills/{name}.md", _MAX_PACKAGE_FILE_BYTES)
    text = body.decode("utf-8")
    if not text.strip():
        raise ValueError("skill file is empty")
    if not text.startswith("---\n"):
        description = ""
        if catalog_entry and isinstance(catalog_entry.get("description"), str):
            description = catalog_entry["description"].strip()
        frontmatter = (
            f"---\nname: {name}\n"
            f"description: {json.dumps(description or f'Paperclip {name} skill')}\n"
            "---\n\n"
        )
        body = frontmatter.encode("utf-8") + body
    return {Path("SKILL.md"): body}


def _atomic_install_tree(root: Path, files: dict[Path, bytes]) -> None:
    """Replace a complete skill directory, restoring the old tree on failure."""
    root.parent.mkdir(parents=True, exist_ok=True)
    staging = Path(tempfile.mkdtemp(prefix=f".{root.name}.staging-", dir=root.parent))
    backup = root.with_name(f".{root.name}.backup-{os.getpid()}")
    moved_old = False
    try:
        for relative, body in files.items():
            destination = staging / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(body)
        if backup.exists():
            shutil.rmtree(backup)
        if root.exists():
            os.replace(root, backup)
            moved_old = True
        os.replace(staging, root)
        if moved_old:
            shutil.rmtree(backup, ignore_errors=True)
    except Exception:
        if moved_old and not root.exists() and backup.exists():
            os.replace(backup, root)
        raise
    finally:
        if staging.exists():
            shutil.rmtree(staging, ignore_errors=True)
        if backup.exists() and root.exists():
            shutil.rmtree(backup, ignore_errors=True)


def _agent_skill_root(target: Path, agent: str, name: str) -> Path:
    prefixes = {
        "claude-code": Path(".claude") / "skills",
        "cursor": Path(".cursor") / "skills",
        "codex": Path(".agents") / "skills",
    }
    return target / prefixes[agent] / name


def _select_agents_and_target(target_dir: str) -> tuple[list[dict], Path]:
    choices = _checkbox(AGENTS, "Select your coding agent(s):")
    selected_agents = [AGENTS[i] for i in choices]
    target = Path(target_dir).expanduser().resolve()
    click.echo(f"  {BOLD}Install directory{RESET}")
    dir_input = click.prompt("  Path", default=str(target), show_default=True)
    target = Path(dir_input).expanduser().resolve()
    if not target.is_dir():
        raise click.ClickException(f"Directory not found: {target}")
    return selected_agents, target


def install_domain_skill(
    base_url: str,
    name: str,
    target_dir: str = ".",
    catalog_entry: dict | None = None,
) -> None:
    """Install a catalog skill for selected agents and register it for refresh."""
    name = validate_installable_skill_name(name)
    install_type = None
    if isinstance(catalog_entry, dict):
        install_type = catalog_entry.get("install_type", catalog_entry.get("package_type"))
    if install_type not in (None, "single", "package"):
        raise click.ClickException(f'Unsupported install type "{install_type}"')
    if isinstance(catalog_entry, dict) and catalog_entry.get("installable") is False:
        raise click.ClickException(f'Skill "{name}" is not installable')

    selected_agents, target = _select_agents_and_target(target_dir)
    click.echo(f"\n  Fetching {name} ...")
    try:
        manifest = None
        if install_type != "single":
            manifest = fetch_skill_manifest(base_url, name)
        if manifest is not None:
            kind = "package"
            files = _package_files(base_url, name, manifest)
            manifest_endpoint = f"/skills/skills/{name}/manifest.json"
        else:
            if install_type == "package":
                raise ValueError("package manifest not found")
            kind = "single"
            files = _single_skill_file(base_url, name, catalog_entry)
            manifest_endpoint = None
    except Exception as exc:
        raise click.ClickException(f"Failed to fetch skill package: {exc}") from exc

    records: list[dict] = []
    failures = 0
    for agent in selected_agents:
        root = _agent_skill_root(target, agent["key"], name)
        try:
            _atomic_install_tree(root, files)
        except OSError as exc:
            failures += 1
            click.echo(f"  {RED}✗ Failed to install for {agent['label']}: {exc}{RESET}")
            continue
        click.echo(f"  {GREEN}✓{RESET} Installed to {BOLD}{root}{RESET}")
        record = {
            "skill": name,
            "kind": kind,
            "agent": agent["key"],
            "root": str(root),
            "entry": str(root / "SKILL.md"),
        }
        if manifest_endpoint:
            record["manifest"] = manifest_endpoint
        if isinstance(catalog_entry, dict) and isinstance(catalog_entry.get("description"), str):
            record["description"] = catalog_entry["description"]
        records.append(record)
    if not records:
        raise click.ClickException("No skills were installed")
    _register_install_records(records)
    if failures:
        click.echo(f"  {DIM}{failures} selected install(s) failed.{RESET}")


# ── Main entry ───────────────────────────────────────────────────


def install_skill(base_url: str, target_dir: str = ".") -> None:
    """Interactive TUI to fetch and install Paperclip skill."""
    click.echo()
    click.echo(
        f"  {BOLD}\u256d\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256e{RESET}"  # noqa: E501
    )
    click.echo(f"  {BOLD}\u2502    Paperclip  Install     \u2502{RESET}")
    click.echo(
        f"  {BOLD}\u2570\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256f{RESET}"  # noqa: E501
    )

    selected_agents, target = _select_agents_and_target(target_dir)

    writers = {
        "claude-code": _write_claude_code,
        "cursor": _write_cursor,
        "codex": _write_codex,
    }

    click.echo("\n  Fetching skill ...")
    content = fetch_agent_skill(base_url)
    if content is None:
        click.echo(f"  {RED}\u2717 Failed to fetch valid skill content from server.{RESET}")
        raise SystemExit(1)

    if not config.repos_enabled():
        content = strip_repos_sections(content)

    installed_keys: list[str] = []
    installed_paths: list[Path] = []
    for agent in selected_agents:
        try:
            path = writers[agent["key"]](content, target)
        except OSError as e:
            click.echo(f"  {RED}\u2717 Failed to install for {agent['label']}: {e}{RESET}")
            continue
        click.echo(f"  {GREEN}\u2713{RESET} Installed to {BOLD}{path}{RESET}")
        installed_keys.append(agent["key"])
        installed_paths.append(path)

    if not installed_keys:
        click.echo(f"\n  {RED}\u2717 No skills were installed.{RESET}")
        raise SystemExit(1)

    # Remember where we installed so `paperclip update` can refresh these
    # files regardless of the directory it is run from.
    _register_skill_paths(installed_paths)

    # Reload reminder
    click.echo()
    click.echo(f"  {BOLD}Next step:{RESET} reload your coding session so the skill is picked up.")
    click.echo()
    if "cursor" in installed_keys:
        click.echo(
            f'  {DIM}\u2022 Cursor:{RESET}      Reload Window  (Cmd/Ctrl+Shift+P \u2192 "Reload Window")'  # noqa: E501
        )
    if "claude-code" in installed_keys:
        click.echo(f"  {DIM}\u2022 Claude Code:{RESET}  Start a new session or run /reload")
    if "codex" in installed_keys:
        click.echo(f"  {DIM}\u2022 Codex:{RESET}        Start a new Codex session")

    # Example query
    click.echo()
    click.echo(f"  {BOLD}Try it out:{RESET}")
    click.echo(f'  From the CLI:      {CYAN}paperclip search "GLP-1 receptor agonists"{RESET}')
    click.echo(
        f"  Prompt your agent: {DIM}using {RESET}{CYAN}/paperclip{RESET}{DIM}, search for recent papers on GLP-1 receptor agonists{RESET}"  # noqa: E501
    )
    click.echo()


def _find_installed_skills() -> tuple[set[Path], set[Path]]:
    """Locate installed skill files via scanning and the install registry.

    Returns ``(standalone, legacy)`` where *standalone* are SKILL.md files
    and *legacy* are AGENTS.md files with sentinel comments. Registry
    entries whose files no longer exist are pruned; newly discovered files
    are backfilled into the registry.
    """
    standalone: set[Path] = set()
    legacy: set[Path] = set()

    for d in _candidate_dirs():
        for rel in _SKILL_RELATIVE_PATHS:
            p = d / rel
            try:
                if p.is_file():
                    standalone.add(p)
            except OSError:
                continue
        agents_path = d / "AGENTS.md"
        if _is_legacy_codex_file(agents_path):
            legacy.add(agents_path)

    registered_records = _read_install_registry()
    domain_records: list[dict] = []
    for record in registered_records:
        p = Path(record["entry"])
        if record["kind"] in {"single", "package"}:
            try:
                if Path(record["root"]).is_dir() and p.is_file():
                    domain_records.append(record)
            except OSError:
                pass
            continue
        if record["kind"] == "legacy_codex":
            if _is_legacy_codex_file(p):
                legacy.add(p)
        else:
            try:
                if p.is_file():
                    standalone.add(p)
            except OSError:
                continue

    core_records = [_record_for_path(path) for path in standalone | legacy]
    current_keys = {
        (record["skill"], record["agent"], record["entry"]) for record in registered_records
    }
    updated_records = core_records + domain_records
    updated_keys = {
        (record["skill"], record["agent"], record["entry"]) for record in updated_records
    }
    try:
        registry_version = json.loads(_registry_file().read_text()).get("version")
    except Exception:
        registry_version = None
    if updated_keys != current_keys or registry_version != 2:
        _write_install_registry(updated_records)

    return standalone, legacy


def _refresh_skill_files(
    base_url: str,
    standalone: set[Path],
    legacy: set[Path],
    silent: bool = False,
) -> int:
    """Refresh core pointers and remove obsolete local domain skill trees."""
    targets: list[tuple[Path, str | None]] = [
        *((p, None) for p in sorted(standalone)),
        *((p, "legacy_codex") for p in sorted(legacy)),
    ]
    domain_installs = [
        record
        for record in _read_install_registry()
        if record["kind"] in {"single", "package"}
        and Path(record["root"]).is_dir()
        and Path(record["entry"]).is_file()
    ]
    total_targets = len(targets) + len(domain_installs)
    if not total_targets:
        if not silent:
            click.echo(f"  {DIM}No installed skill files found.{RESET}")
        return 0

    if targets:
        content = fetch_agent_skill(base_url, timeout=5)
        if content is not None and not config.repos_enabled():
            content = strip_repos_sections(content)
        if content is None:
            if not silent:
                click.echo(
                    f"  {DIM}Could not fetch the latest core skill — "
                    f"{len(targets)} installed file(s) left unchanged.{RESET}"
                )
        else:
            for path, kind in targets:
                try:
                    if kind == "legacy_codex":
                        _write_codex_legacy(content, path.parent)
                    else:
                        path.write_text(content)
                    if not silent:
                        click.echo(f"  {DIM}Updated {_display_path(path)}{RESET}")
                except Exception:
                    if not silent:
                        click.echo(f"  {DIM}Could not update {_display_path(path)}{RESET}")

    all_records = _read_install_registry()
    retained_records = [
        record for record in all_records if record["kind"] not in {"single", "package"}
    ]
    for record in domain_installs:
        root = Path(record["root"])
        try:
            shutil.rmtree(root)
            if not silent:
                click.echo(
                    f"  {DIM}Removed obsolete local copy {_display_path(root)}; "
                    f"the content now loads remotely.{RESET}"
                )
        except Exception:
            retained_records.append(record)
            if not silent:
                click.echo(f"  {DIM}Could not remove {_display_path(root)}{RESET}")
    if domain_installs:
        _write_install_registry(retained_records)

    return total_targets


def refresh_installed_skills(base_url: str, silent: bool = False) -> int:
    """Update any previously installed skill files.

    Called on login and periodically during command execution so users
    always have the latest core pointer without re-running `paperclip install`.
    Registered domain skill and workflow copies from older releases are removed
    because domain references and account-enabled routines now load remotely.
    Looks for installs in the cwd, its ancestors, the home directory, and
    any locations recorded in the install registry.

    When silent=True, suppresses all output (used for background refresh).
    Returns the number of skill files found.
    """
    standalone, legacy = _find_installed_skills()
    return _refresh_skill_files(base_url, standalone, legacy, silent=silent)


def find_and_refresh_all_skills(base_url: str) -> None:
    """Find every skill install on the machine and update them all.

    Used by interactive `paperclip update`. In addition to the fast lookup
    paths, runs a bounded scan of the home directory so installs in other
    projects are found too. Everything found is recorded in the registry and
    refreshed. If nothing is installed anywhere, offers a fresh install.
    """
    standalone, legacy = _find_installed_skills()
    try:
        standalone |= _scan_home_for_skills()
    except Exception:
        pass  # a scan failure must never block refreshing the known installs

    domain_installs = [
        record for record in _read_install_registry() if record["kind"] in {"single", "package"}
    ]
    if not standalone and not legacy and not domain_installs:
        click.echo(f"  {DIM}No installed skill files found.{RESET}")
        if sys.stdin.isatty():
            click.echo()
            install_skill(base_url)
        else:
            click.echo(f"  Run {CYAN}paperclip install{RESET} to set them up.")
        return

    _write_install_registry(
        [_record_for_path(path) for path in standalone | legacy] + domain_installs
    )
    _refresh_skill_files(base_url, standalone, legacy)


def _standalone_skill_paths(cwd: Path | None = None) -> list[Path]:
    """Installed SKILL.md locations for Claude Code, Cursor, and Codex."""
    base = cwd or Path.cwd()
    paths = {base / rel for rel in _SKILL_RELATIVE_PATHS}
    paths.update(
        Path(record["entry"]) for record in _read_install_registry() if record["kind"] == "system"
    )
    return sorted(paths)


def apply_repos_preference(base_url: str, enabled: bool) -> None:
    """Re-render installed skill files to match the repos on/off preference.

    On enable we re-fetch the full skill from the server (restores any
    previously stripped sections). On disable we both refresh (which now
    strips, since the preference is already persisted) and strip the
    standalone SKILL.md files in place so the change applies even offline.
    """
    try:
        refresh_installed_skills(base_url, silent=True)
    except Exception:
        pass

    if not enabled:
        for path in _standalone_skill_paths():
            try:
                if path.exists():
                    path.write_text(strip_repos_sections(path.read_text()))
            except Exception:
                pass


_SKILL_CHECK_FILE = Path.home() / ".paperclip" / ".last_skill_refresh"
_SKILL_REFRESH_INTERVAL = 4 * 3600  # 4 hours


def maybe_refresh_skills(base_url: str) -> None:
    """Silently refresh installed skill files if the cooldown has elapsed.

    Safe to call on every command — checks a timestamp file and only
    hits the network every 4 hours. All failures are swallowed.
    """
    try:
        last = 0.0
        try:
            last = float(_SKILL_CHECK_FILE.read_text().strip())
        except (OSError, ValueError):
            last = 0.0  # missing or corrupt timestamp → treat as expired
        now = time.time()
        if last > now:
            last = 0.0  # future timestamp (clock skew) → treat as expired
        if now - last < _SKILL_REFRESH_INTERVAL:
            return

        found = refresh_installed_skills(base_url, silent=True)

        # Only burn the cooldown when something was actually refreshed, so
        # a run from a directory with no install doesn't block the next
        # refresh of the real install location. Finding zero targets is
        # cheap (filesystem stats only — no network).
        if found > 0:
            _SKILL_CHECK_FILE.parent.mkdir(parents=True, exist_ok=True)
            _SKILL_CHECK_FILE.write_text(str(time.time()))
    except Exception:
        pass
